<?php
use App\Core\Csrf;use App\Core\Session;
$error=Session::pullFlash('error');$success=Session::pullFlash('success');$optional=(int)($lesson['is_required']??1)===0||(int)($lesson['phase_required']??1)===0;
$types=['theory'=>['TEORIA','T','theory'],'example'=>['EXEMPLO','E','example'],'warning'=>['ATENÇÃO','!','warning'],'summary'=>['RESUMO','R','summary'],'comparison'=>['COMPARAÇÃO','↔','comparison'],'memory'=>['MEMORIZE','M','memory'],'case_study'=>['CASO PRÁTICO','C','case'],'image'=>['IMAGEM','I','media'],'video'=>['VÍDEO','V','media'],'question'=>['QUESTÃO','?','question']];$meta=$types[$currentBlock['block_type']??'theory']??$types['theory'];$visited=(int)($progress['blocks_viewed']??0);$pct=$totalBlocks?min(100,round(($visited/$totalBlocks)*100)):0;
$render=static function(string $text):string{$text=trim($text);if($text==='')return '<p class="content-p muted">Conteúdo não preenchido.</p>';$parts=preg_split('/\R\R+/',$text)?:[];$html='';foreach($parts as $p){$p=trim($p);if($p==='')continue;$lines=array_values(array_filter(array_map('trim',preg_split('/\R/',$p)?:[]),fn($x)=>$x!==''));$isTable=count($lines)>=2&&count(array_filter($lines,fn($x)=>substr_count($x,' | ')>=1))===count($lines);if($isTable){$rows=array_map(fn($x)=>array_map('trim',explode(' | ',$x)),$lines);$counts=array_unique(array_map('count',$rows));if(count($counts)===1){$html.='<div class="table-wrap"><table class="content-table">';foreach($rows as $ri=>$row){$html.='<tr>';foreach($row as $cell){$tag=$ri===0?'th':'td';$html.='<'.$tag.'>'.e($cell).'</'.$tag.'>';}$html.='</tr>';}$html.='</table></div>';continue;}}$bullets=count($lines)>1;$ordered=true;foreach($lines as $line){if(!preg_match('/^(?:•|\-|\*)\s+/u',$line))$bullets=false;if(!preg_match('/^\d+[\.\)]\s+/u',$line))$ordered=false;}if($bullets||$ordered){$tag=$ordered?'ol':'ul';$html.='<'.$tag.' class="content-list">';foreach($lines as $line){$line=preg_replace($ordered?'/^\d+[\.\)]\s+/u':'/^(?:•|\-|\*)\s+/u','',$line);$html.='<li>'.e($line).'</li>';}$html.='</'.$tag.'>';continue;}if(preg_match('/^([^:\n]{2,55}):\s*(.+)$/us',$p,$m)&&!str_contains($m[1],'.'))$html.='<p class="content-p"><strong>'.e(trim($m[1])).':</strong> '.nl2br(e(trim($m[2]))).'</p>';else $html.='<p class="content-p">'.nl2br(e($p)).'</p>'; }return $html;};
?>
