 if($currentIndex<$totalBlocks):?><a class="primary" data-next href="<?=e(url('/aula/'.$lesson['id'].'?bloco='.($currentIndex+1)))?>">Próximo →</a><?php else:?><form class="inline" action="<?=e(url('/aula/'.$lesson['id'].'/concluir'))?>" method="post"><?=Csrf::input()?><button class="success" type="submit">Concluir <?=$optional?'leitura':'aula'?> ✓</button></form><?php endif;?></footer></section></section>
